WITH filtered_payments AS (SELECT *, INITCAP(TRIM(method)) AS method_title FROM payments WHERE status = 'SUCCESS' AND method = 'card'), agg AS (SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, MIN(paid_at) AS min_paid_at FROM filtered_payments GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM agg
